const cases = [
  { input: '카드가 두 번 결제됐어요',      want: 'payment' },
  { input: '비밀번호를 잊어버렸어요',        want: 'account' },
  { input: '배송이 언제 오나요',            want: 'shipping' },
];
let pass = 0;
for (const c of cases) {
  const got = await classify(c.input);   // 우리가 재는 대상
  if (got === c.want) pass++;            // 결정적 채점
}
const score = pass / cases.length;       // 0.0 ~ 1.0
// 이 score 가 기준선. 바꿀 때마다 이 숫자를 비교한다.

// 요약 품질: 하나의 점수로 뭉개지 말고 기준을 쪼갠다
function scoreSummary(source, summary) {
  return {
    factual: allFactsInSource(summary, source),  // 없는 사실 지어냈나 (0~1)
    concise: summary.length <= source.length * 0.3, // 충분히 짧나
    format:  /^- /.test(summary),                  // 요청한 불릿 형식인가
  };
}
// 각 기준을 따로 추적하면 '어느 축이 나빠졌나'가 보인다

const judgePrompt = `아래 답변을 채점하라.
기준:
 (1) 근거 문서에 있는 사실만 말했나 (지어낸 사실 = 0)
 (2) 질문에 직접 답했나
 (3) 요청한 형식(불릿 3개)을 지켰나
각 항목 0 또는 1 로, 이유 한 줄과 함께 JSON 으로:
{"factual":0|1, "answered":0|1, "format":0|1, "why":"..."}

[질문] ${q}
[근거] ${context}
[답변] ${answer}`;
// 낮은 temperature · 구조화 출력 · 근거를 함께 준다
